import * as React from 'react';
import { cn } from '@/lib/utils';

export interface Suggestion {
  id: string;
  text: string;
  type?: 'action' | 'query' | 'follow-up';
}

export interface SuggestionsProps {
  suggestions: Suggestion[];
  onSelect?: (suggestion: Suggestion) => void;
  className?: string;
  maxDisplay?: number;
}

const Suggestions = React.forwardRef<HTMLDivElement, SuggestionsProps>(
  ({ suggestions, onSelect, className, maxDisplay = 4, ...props }, ref) => {
  const displaySuggestions = maxDisplay ? suggestions.slice(0, maxDisplay) : suggestions;

  if (suggestions.length === 0) {
    return null;
  }

  return (
    <div ref={ref} className={cn('mt-4 space-y-2', className)} {...props}>
      {displaySuggestions.map((suggestion) => (
        <button
          key={suggestion.id}
          className={cn(
            'w-full text-left h-auto py-2 px-3 text-sm rounded-md',
            'hover:bg-accent hover:text-accent-foreground',
            'transition-colors',
            'text-muted-foreground',
            'focus:outline-none focus:ring-2 focus:ring-ring'
          )}
          onClick={() => onSelect?.(suggestion)}
        >
          {suggestion.text}
        </button>
      ))}
    </div>
  );
});
Suggestions.displayName = 'Suggestions';

export { Suggestions };

{
  "id": "suggestions",
  "name": "Suggestions",
  "tier": "molecule",
  "description": "Displays clickable follow-up prompts for AI interactions.",
  "designIntent": "Help users discover useful next actions without composing every prompt from scratch.",
  "props": [
    {
      "name": "suggestions",
      "type": "Suggestion[]",
      "required": true,
      "description": "Suggestions to display."
    },
    {
      "name": "onSelect",
      "type": "(suggestion: Suggestion) => void",
      "required": false,
      "description": "Called when a suggestion is selected."
    },
    {
      "name": "maxDisplay",
      "required": false,
      "defaultValue": "4",
      "type": "number",
      "description": "Maximum number of suggestions to display before truncating"
    }
  ],
  "examples": [
    {
      "title": "Follow-up prompts",
      "code": "<Suggestions suggestions={[{ id: '1', text: 'Show me an example' }]} />"
    }
  ],
  "accessibility": [
    {
      "feature": "Keyboard activation",
      "implementation": "Suggestions are native buttons."
    }
  ],
  "package": "@slipstream-ui/ai",
  "importPath": "@slipstream-ui/ai",
  "version": "0.0.1",
  "sourceDir": "suggestion",
  "exportName": "Suggestions"
}
